1	/**
2	 * The template toolkit shared by every game's code generator: the indentation-aware `code` tag,
3	 * seeded numbers, mod naming, effects parsed from the prompt and the feature list.
4	 */
5	import type { CategoryKey, CategoryMeta, CodeLanguage, Game, ModelId, ModFile } from "@/lib/types";
6	
7	export interface TemplateInput {
8	  game: Game;
9	  category: CategoryMeta;
10	  modName: string;
11	  prompt: string;
12	  model: ModelId;
13	  version: number;
14	}
15	
16	/* ───────────── utilities ───────────── */
17	
18	const EMPTY = "\u0000";
19	
20	/**
21	 * Indentation-aware template tag: strips the common indent, re-indents multi-line
22	 * interpolations to the placeholder's column and drops lines whose only content was
23	 * an empty interpolation.
24	 */
25	export function code(strings: TemplateStringsArray, ...vals: unknown[]): string {
26	  let out = "";
27	  strings.forEach((s, i) => {
28	    out += s;
29	    if (i >= vals.length) return;
30	    const v = vals[i];
31	    let str = Array.isArray(v)
32	      ? v.filter((x) => x !== false && x != null && x !== "").map((x) => String(x).replace(/\n+$/, "")).join("\n")
33	      : v === false || v == null || v === ""
34	        ? ""
35	        : String(v).replace(/\n+$/, "");
36	    if (!str) str = EMPTY;
37	    const lineStart = out.slice(out.lastIndexOf("\n") + 1);
38	    const indent = lineStart.match(/^[ \t]*/)![0];
39	    out += str
40	      .split("\n")
41	      .map((l, j) => (j === 0 || !l ? l : indent + l))
42	      .join("\n");
43	  });
44	  const lines = out
45	    .replace(/^\n/, "")
46	    .split("\n")
47	    .filter((l) => l.trim() !== EMPTY)
48	    .map((l) => l.replaceAll(EMPTY, ""));
49	  while (lines.length && !lines[lines.length - 1].trim()) lines.pop();
50	  const min = Math.min(...lines.filter((l) => l.trim()).map((l) => l.match(/^ */)![0].length));
51	  return (
52	    lines
53	      .map((l) => l.slice(Number.isFinite(min) ? min : 0).trimEnd())
54	      .join("\n")
55	      .replace(/\n{3,}/g, "\n\n") + "\n"
56	  );
57	}
58	
59	export function hashStr(s: string) {
60	  let h = 2166136261;
61	  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
62	  return h >>> 0;
63	}
64	
65	export function mulberry32(seed: number) {
66	  let a = seed;
67	  return () => {
68	    a |= 0;
69	    a = (a + 0x6d2b79f5) | 0;
70	    let t = Math.imul(a ^ (a >>> 15), 1 | a);
71	    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
72	    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
73	  };
74	}
75	
76	export function languageForPath(path: string): CodeLanguage {
77	  const ext = path.split(".").pop()?.toLowerCase();
78	  switch (ext) {
79	    case "java":
80	      return "java";
81	    case "psc":
82	      return "papyrus";
83	    case "cs":
84	      return "csharp";
85	    case "lua":
86	      return "lua";
87	    case "glsl":
88	    case "fsh":
89	    case "vsh":
90	    case "fx":
91	      return "glsl";
92	    case "json":
93	      return "json";
94	    case "md":
95	      return "markdown";
96	    case "xml":
97	      return "xml";
98	    case "toml":
99	    case "properties":
100	    case "txt":
101	      return ext === "txt" ? "text" : "toml";
102	    default:
103	      return "text";
104	  }
105	}
106	
107	export const file = (path: string, content: string): ModFile => ({ path, language: languageForPath(path), content });
108	
109	/* ───────────── identity & numbers ───────────── */
110	
111	export function identity(modName: string) {
112	  const words = modName.replace(/[^A-Za-z0-9 ]+/g, " ").split(/\s+/).filter(Boolean);
113	  let cls = words.map((w) => w[0].toUpperCase() + w.slice(1)).join("");
114	  if (!cls) cls = "AstralMod";
115	  if (/^\d/.test(cls)) cls = `Cy${cls}`;
116	  const snake = words.join("_").toLowerCase() || "astral_mod";
117	  return { cls, snake: /^\d/.test(snake) ? `cy_${snake}` : snake, kebab: snake.replace(/_/g, "-") };
118	}
119	
120	export function numbers(input: TemplateInput) {
121	  const rnd = mulberry32(hashStr(`${input.game.id}|${input.category.key}|${input.modName}|${input.version}`));
122	  const r = (a: number, b: number, d = 1) => Number((a + rnd() * (b - a)).toFixed(d));
123	  const i = (a: number, b: number) => Math.round(a + rnd() * (b - a));
124	  return {
125	    power: r(5, 14),
126	    cooldown: r(1.5, 8),
127	    radius: i(3, 9),
128	    duration: i(4, 12),
129	    chance: r(0.12, 0.4, 2),
130	    health: i(18, 90) * 10,
131	    speed: r(0.24, 0.42, 2),
132	    interval: i(2, 10),
133	    xp: i(12, 80),
134	    hue: i(0, 359),
135	    intensity: r(0.6, 1.4, 2),
136	    rnd,
137	  };
138	}
