318	export const DEFAULT_EFFECTS: Record<CategoryKey, EffectKey[]> = {
319	  weapons: ["storm", "fire", "frost"],
320	  creatures: ["void", "poison", "summon"],
321	  worlds: ["lunar", "frost"],
322	  mechanics: ["auto", "neon"],
323	  shaders: ["lunar", "neon"],
324	  magic: ["storm", "lunar", "frost"],
325	  quests: ["lunar", "void"],
326	  interface: ["neon", "auto"],
327	  audio: ["lunar", "neon"],
328	  vehicles: ["flight", "neon"],
329	  items: ["auto", "heal"],
330	  characters: ["heal", "lunar"],
331	};
332	
333	export function effectsFor(input: TemplateInput): Effect[] {
334	  const text = `${input.prompt} ${input.modName}`.toLowerCase();
335	  const hits = EFFECTS.filter((e) => e.re.test(text)).slice(0, 2);
336	  if (hits.length) return hits;
337	  const pool = DEFAULT_EFFECTS[input.category.key];
338	  const key = pool[hashStr(input.modName) % pool.length];
339	  return [EFFECTS.find((e) => e.key === key)!];
340	}
341	
342	export const sub = (s: string, target: string, source: string, extra: Record<string, string> = {}) => {
343	  let out = s.replaceAll("TARGET", target).replaceAll("SOURCE_SRC", extra.SOURCE_SRC ?? "source").replaceAll("SOURCE", source);
344	  for (const [k, v] of Object.entries(extra)) out = out.replaceAll(k, v);
345	  return out;
346	};
347	
348	export type Arch = "item" | "entity" | "world" | "system" | "visual";
349	export const ARCH: Record<CategoryKey, Arch> = {
350	  weapons: "item",
351	  items: "item",
352	  magic: "item",
353	  creatures: "entity",
354	  characters: "entity",
355	  vehicles: "entity",
356	  worlds: "world",
357	  mechanics: "system",
358	  quests: "system",
359	  interface: "system",
360	  audio: "system",
361	  shaders: "visual",
362	};
363	
364	export const MODEL_NAME: Record<ModelId, string> = { katara: "Katara", sokka: "Sokka", yako: "Yako" };
365	
366	export function deriveFeatures(input: TemplateInput): string[] {
367	  const n = numbers(input);
368	  const fx = effectsFor(input).map((e) => e.label);
369	  const cat = input.category.key;
370	  const byCat: Record<CategoryKey, string> = {
371	    weapons: `${n.power} bonus damage with a ${n.cooldown}s active ability`,
372	    items: `Right-click ability on a ${n.cooldown}s cooldown`,
373	    magic: `Spell radius of ${n.radius} blocks, ${n.cooldown}s recast`,
374	    creatures: `${n.health} HP with a second phase below 40%`,
375	    characters: "Daily schedule, gift tastes and heart events",
376	    vehicles: `Top speed tuned to ${Math.round(n.speed * 400)} km/h with drift boost`,
377	    worlds: `Generates every ~${n.interval * 100} blocks with custom loot`,
378	    mechanics: `Runs every ${n.interval}s without touching vanilla saves`,
379	    quests: "Multi-stage objectives with journal entries",
380	    interface: "Toggleable overlay with scale + opacity settings",
381	    audio: "Adaptive layers that crossfade with game state",
382	    shaders: `Color grade at ${Math.round(n.intensity * 100)}% intensity with bloom`,
383	  };
384	  const out = [...fx, byCat[cat]];
385	  if (input.model !== "katara") out.push("Every number exposed in config");
386	  if (input.model === "yako") out.push("Covered by unit tests");
387	  return out.slice(0, 5);
388	}
