94	  }
95	  const head = text.split(STOP_CLAUSE)[0] ?? text;
96	  const words = head
97	    .replace(/[^\p{L}\p{N}\s-]/gu, " ")
98	    .split(/\s+/)
99	    .filter((w) => w && !FILLER.has(w.toLowerCase()));
100	
101	  let picked = words.slice(0, 4).map(titleCase);
102	  if (picked.length === 1) {
103	    const flavor = FLAVOR.find(([re]) => re.test(prompt.toLowerCase()))?.[1];
104	    if (flavor && flavor.toLowerCase() !== picked[0].toLowerCase()) picked = [flavor, ...picked];
105	  }
106	  let name = picked.join(" ");
107	  if (!name) name = `${FLAVOR.find(([re]) => re.test(prompt.toLowerCase()))?.[1] ?? "Astral"} ${CATEGORY_BY_KEY[category].label.replace(/s$/, "")}`;
108	  if (name.length > 34) name = name.slice(0, 34).replace(/\s+\S*$/, "");
