152	export function diffStats(prev: ModFile[] | undefined, next: ModFile[]) {
153	  const count = (files: ModFile[]) => {
154	    const m = new Map<string, number>();
155	    for (const f of files) for (const line of f.content.split("\n")) if (line.trim()) m.set(line, (m.get(line) ?? 0) + 1);
156	    return m;
157	  };
158	  const a = count(prev ?? []);
159	  const b = count(next);
160	  let additions = 0;
161	  let deletions = 0;
162	  for (const [line, n] of b) additions += Math.max(0, n - (a.get(line) ?? 0));
163	  for (const [line, n] of a) deletions += Math.max(0, n - (b.get(line) ?? 0));
164	  return { additions, deletions };
165	}
