214	export async function* forgeStream(req: ForgeRequest, signal?: AbortSignal): AsyncGenerator<GenEvent> {
215	  const model = MODEL_BY_ID[req.model] ?? MODEL_BY_ID.katara;
216	  const prompt = req.prompt.trim().slice(0, 2000);
217	  const ctx = req.context ?? {};
218	  const refining = Boolean(ctx.modId && ctx.modName);
219	
220	  const jobId = `job_${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;
221	  yield { type: "start", jobId, model: model.id, credits: model.credits };
222	  await sleep(320);
223	
224	  const games = [...GAMES, ...(req.games ?? [])];
225	  const route = refining && ctx.gameId && ctx.category ? { gameId: ctx.gameId, category: ctx.category } : routePrompt(prompt, ctx, games);
226	  const game = games.find((g) => g.id === route.gameId) ?? GAMES[0];
227	  const category = CATEGORY_BY_KEY[route.category];
228	  const modName = refining ? ctx.modName! : deriveModName(prompt, game, route.category);
229	  const version = refining ? Math.max(2, ctx.version ?? 2) : 1;
230	  const modId = refining ? ctx.modId! : `${route.gameId}-${slugify(modName) || "mod"}-${Math.random().toString(36).slice(2, 6)}`;
231	
232	  const input: TemplateInput = { game, category, modName, prompt, model: model.id, version };
233	  const files = buildModFiles(input);
234	  const features = deriveFeatures(input);
235	  const steps = planThinking(input, files, refining);
236	
237	  // First two steps happen before we know the branch — that's when the core is "thinking".
238	  for (let i = 0; i < steps.length; i++) {
239	    if (signal?.aborted) return;
240	    const s = steps[i];
241	    const id = `s${i}`;
242	    yield { type: "think", id, label: s.label, detail: s.detail };
243	    if (i === 1) {
244	      yield {
245	        type: "route",
246	        gameId: game.id,
247	        category: category.key,
248	        modName,
249	        modId,
250	        summary: refining ? prompt : features[0] ?? category.description,
251	        tags: features.slice(0, 3).map((f) => f.split(" ").slice(0, 2).join(" ").toLowerCase()),
252	      };
253	    }
254	    await sleep(s.ms * rand(0.75, 1.15) + (model.id === "yako" ? 250 : 0));
255	    yield { type: "think-done", id };
256	  }
257	
258	  for (let fi = 0; fi < files.length; fi++) {
259	    const f = files[fi];
260	    const id = `w${fi}`;
261	    yield { type: "think", id, label: `Writing ${f.path.split("/").pop()}`, detail: f.path };
262	    yield { type: "file", path: f.path, language: f.language };
263	    const content = f.content;
264	    // Supporting files stream faster than the main source file.
265	    const boost = fi === 0 ? 1 : 1.8;
266	    let i = 0;
267	    while (i < content.length) {
268	      if (signal?.aborted) return;
269	      const size = Math.round(rand(model.chunk[0], model.chunk[1]) * boost);
270	      yield { type: "chunk", path: f.path, text: content.slice(i, i + size) };
271	      i += size;
272	      await sleep(model.tick * rand(0.6, 1.4));
273	    }
274	    yield { type: "file-done", path: f.path };
275	    yield { type: "think-done", id };
276	    await sleep(160);
277	  }
278	
279	  const pid = "pkg";
280	  yield { type: "think", id: pid, label: "Packaging & signing", detail: `${modName} v${version} · ${files.length} files` };
281	  await sleep(520);
282	  yield { type: "think-done", id: pid };
283	
284	  yield {
285	    type: "done",
286	    summary: refining ? prompt : features.join(" · "),
287	    notes: buildModNotes(input),
288	  };
289	}
