// usage: node gen.mjs <model> "<prompt>" [outDir]
import fs from "node:fs";
import path from "node:path";

const [model, prompt, outDir] = process.argv.slice(2);
const res = await fetch("http://localhost:3000/api/generate", {
  method: "POST",
  headers: { "content-type": "application/json" },
  body: JSON.stringify({ prompt, model }),
});
const text = await res.text();
const files = new Map();
let route;
for (const line of text.split("\n")) {
  if (!line.trim()) continue;
  const ev = JSON.parse(line);
  if (ev.type === "route") route = ev;
  if (ev.type === "file") files.set(ev.path, "");
  if (ev.type === "chunk") files.set(ev.path, files.get(ev.path) + ev.text);
  if (ev.type === "error") console.log("ERROR", ev.message);
}
console.log(`## ${route?.gameId} / ${route?.category} / ${route?.modName}`);
for (const [p, c] of files) {
  if (outDir) {
    const full = path.join(outDir, p);
    fs.mkdirSync(path.dirname(full), { recursive: true });
    fs.writeFileSync(full, c);
  }
  console.log(`\n===== ${p} (${c.split("\n").length} lines) =====\n${outDir ? "" : c}`);
}

